# Generates map/worlds/w12i.js, w13.js, w14.js, w15.js (Season 2 test maps, 2D).
import json, os
import os
OUT=os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'map', 'worlds') + '/'
COMMON_PROPS = r"""
  const {px,box,shadow,txt}=K; const G=()=>K.g();
  const tri=(c,x1,y1,x2,y2,x3,y3)=>{const g=G();g.fillStyle='#1b1220';g.beginPath();g.moveTo(x1-1,y1+1);g.lineTo(x2,y2-1);g.lineTo(x3+1,y3+1);g.fill();g.fillStyle=c;g.beginPath();g.moveTo(x1,y1);g.lineTo(x2,y2);g.lineTo(x3,y3);g.fill();};
  const dome=(c,x,y,r)=>{const g=G();g.fillStyle='#1b1220';g.beginPath();g.arc(x,y,r+1,Math.PI,0);g.fill();g.fillStyle=c;g.beginPath();g.arc(x,y,r,Math.PI,0);g.fill();px('rgba(255,255,255,.35)',x-r*0.5,y-r*0.7,2,r*0.5);};
  /* the airport at the end of every Season 2 world: the plane to the next country */
  K.P.s2airport=function(X,Y,to){shadow(X+30,Y+2,40,4);box('#c9ccd2',X,Y-18,60,18);px('#7ec8ff',X+4,Y-14,52,5);box('#8a90a0',X+44,Y-34,10,16);px('#7ec8ff',X+45,Y-32,8,4);
    const g=G();g.fillStyle='#1b1220';g.fillRect(X+66,Y-14,38,7);g.fillStyle='#f4f1e8';g.fillRect(X+67,Y-13,36,5);px('#e8364b',X+67,Y-11,36,1);px('#1b1220',X+80,Y-20,12,7);px('#f4f1e8',X+81,Y-19,10,6);px('#1b1220',X+98,Y-21,6,8);px('#e8364b',X+99,Y-20,4,7);
    K.P.label(X+40,Y-48,'AIRPORT');if(to)K.P.label(X+40,Y+6,'TO '+to);};
"""
def js(v): return json.dumps(v)
def make(fname, n, hud, name, where, marks, extra_props_js, world):
    stops=',\n      '.join("{at:%s,name:%s,st:%s%s}"%(js(s[0]),js(s[1]),js(s[2]),(',via:'+js(s[3])) if len(s)>3 else '') for s in world['stops'])
    props=',\n      '.join(js(p)[1:-1].join(['[',']']) if False else js(p) for p in world['props'])
    body = "/* World %d: %s (Season 2 test, 2D; docs/WORLDS-12-15-PLAN.md). Generated by hand-kept data: edit freely. */\n(function(K){%s%s\n  K.W.push({n:%d,flat:true,hud:%s,name:%s,\n    where:%s,\n    marks:%s,\n    size:[1000,540],ground:%s,water:%s,cliff:'rock',path:'tan',\n    rivers:%s,\n    lakes:%s,\n    zones:[%s],\n    roads:%s,\n    stops:[\n      %s],\n    props:[\n      %s],\n    scatter:%s,\n    anim:%s});\n})(KINAN);\n" % (
        n, hud, COMMON_PROPS, extra_props_js, n, js(hud), js(name), js(where), js(marks), js(world['ground']), js(world['water']),
        js(world['rivers']), js(world['lakes']), ','.join(world['zones']), js(world['roads']), stops, props, js(world['scatter']), js(world['anim']))
    open(OUT+fname,'w').write(body)

